<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue';
import {acceptFamilyEntitlements,familyAccessGeneration,suspendFamilyAccess} from '../platform/familyAccess';
import { accountApi, AccountApiError, type FamilyWorkspace } from '../platform/account';
import { createBillingClient,billingRequest,bindBillingOrder,completeBillingRequest,BillingApiError,type Entitlement,type Product,type BillingOrder } from '../platform/billing';
const props=defineProps<{accountId:string;family:FamilyWorkspace}>();
const client=createBillingClient(props.family.id),features=ref<Entitlement[]>([]),products=ref<Product[]>([]),orders=ref<BillingOrder[]>([]),providerReady=ref(false),configured=ref(false),canPurchase=ref(false),busy=ref(false),error=ref(''),message=ref(''),revoked=ref(false);
let paymentPlatform=false;
// #ifdef H5
paymentPlatform=true;
// #endif
const manager=computed(()=>['owner','admin'].includes(props.family.role));
const names={profiles:'使用人管理',scenarios:'场景管理',analytics:'分析与报告'};
const states:Record<string,string>={CREATED:'下单结果待确认',PENDING:'等待支付',PAID:'付款已核验',CLOSED:'订单已关闭',REFUND_PENDING:'退款处理中',REFUNDED:'退款已确认',FAILED:'付款失败'};
let generation=0,disposed=false;onUnmounted(()=>{disposed=true;generation++;});
type Current=()=>boolean;
async function run(action:(current:Current)=>Promise<void>){if(disposed||busy.value||revoked.value)return;const token=++generation;busy.value=true;error.value='';message.value='';try{const session=await accountApi.me();if(token!==generation)return;if(session.account.id!==props.accountId)throw new BillingApiError(403,'账户已变化，请重新进入家庭功能。');await action(()=>!disposed&&token===generation);}catch(e){if(token===generation){if((e instanceof BillingApiError||e instanceof AccountApiError)&&[401,403].includes(e.status)){revoked.value=true;suspendFamilyAccess(props.accountId,props.family.id);features.value=[];products.value=[];orders.value=[];}error.value=e instanceof Error?e.message:'操作失败';}}finally{if(token===generation)busy.value=false;}}
async function refresh(current:Current){const accessToken=familyAccessGeneration();const [rights,catalog,history]=await Promise.all([client.entitlements(),client.products(),manager.value?client.orders():Promise.resolve([])]);if(!current())return;features.value=rights.features;acceptFamilyEntitlements(props.accountId,props.family.id,rights.features,accessToken,rights.role);configured.value=rights.configured;products.value=catalog.products;providerReady.value=catalog.providerConfigured;canPurchase.value=catalog.canPurchase&&paymentPlatform;orders.value=history;}
onMounted(()=>{void run(refresh);});
const price=(amount:number)=>`¥${(amount/100).toFixed(2)}`;
async function buy(product:Product){if(!canPurchase.value)return;const choice=await uni.showModal({title:`为 ${props.family.name} 开启功能？`,content:`${product.title} · ${price(product.amountMinor)} · ${product.durationDays} 天。仅开启 ${names[product.feature]}，其他模块分别选择。下单结果未知时沿用原编号重试。`,confirmText:'确认下单'});if(!choice.confirm||disposed)return;void run(async(current)=>{const result=await client.create(product.id,billingRequest(props.accountId,props.family.id,product.id));if(!current())return;if(result.order.familyId!==props.family.id)throw new Error('订单归属不正确');bindBillingOrder(props.accountId,props.family.id,product.id,result.order.id);if(['PAID','CLOSED','REFUNDED','FAILED'].includes(result.order.status))completeBillingRequest(props.accountId,props.family.id,product.id,result.order.id);if(!current())return;await refresh(current);if(!current())return;message.value=result.order.status==='PAID'?'付款已由服务端核验。':['CLOSED','REFUNDED','FAILED'].includes(result.order.status)?'这笔重试订单已结束。核对订单后，可再次点击下单建立新订单。':'订单已建立，请查看订单并前往支付，付款后查询结果。';});}
function query(order:BillingOrder){void run(async(current)=>{const result=await client.query(order.id);if(!current())return;if(['PAID','CLOSED','REFUNDED','FAILED'].includes(result.status))completeBillingRequest(props.accountId,props.family.id,order.productId,order.id);if(!current())return;await refresh(current);if(!current())return;message.value=`支付结果：${states[result.status]||'等待核验'}`;});}
async function closeOrder(order:BillingOrder){const choice=await uni.showModal({title:'关闭这笔未完成订单？',content:'服务端确认关闭后，才能放心重新下单；若已付款，应查询付款结果。',confirmText:'确认关单'});if(choice.confirm&&!disposed)void run(async(current)=>{const result=await client.close(order.id);if(!current())return;if(result.status==='CLOSED')completeBillingRequest(props.accountId,props.family.id,order.productId,order.id);if(!current())return;await refresh(current);if(!current())return;message.value=states[result.status]||'结果待确认';});}
async function refund(order:BillingOrder){const choice=await uni.showModal({title:'申请整单退款？',content:`申请 ${price(order.amountMinor)} 退款。受理不等于到账，退款成功后撤销这笔订单提供的功能权益；已有资料保留。`,confirmText:'申请退款'});if(choice.confirm&&!disposed)void run(async(current)=>{await client.refund(order.id,'家庭用户申请整单退款');if(!current())return;await refresh(current);if(!current())return;message.value='退款申请已提交，请查询服务端确认结果。';});}
async function openCheckout(order:BillingOrder){if(!paymentPlatform){error.value='请在网页版使用当前支付渠道';return;}if(order.status!=='PENDING'||!order.checkoutUrl)return;try{const url=new URL(order.checkoutUrl);if(url.protocol!=='https:'||url.hostname!=='wx.tenpay.com')throw new Error('付款链接未通过校验');const choice=await uni.showModal({title:'前往支付渠道？',content:`${order.title} · ${price(order.amountMinor)}。链接短期有效，返回页面后请查询支付结果，本页不会仅凭回跳认定成功。链接失效时，先查询并关闭未付款订单，再明确重新下单。`,confirmText:'前往支付'});
// #ifdef H5
if(choice.confirm&&!disposed&&!revoked.value)window.open(url.href,'_blank','noopener,noreferrer');
// #endif
}catch(e){error.value=e instanceof Error?e.message:'付款链接不可用';}}
</script>
<template>
 <view class="billing-manager"><text class="section-title">{{family.name}} · 家庭功能</text><text class="modal-copy">各模块独立开启；到期或退款后已有资料仍可查看。人工测试开通与真实购买分别标明。</text><text v-if="error" role="alert" class="error-copy">{{error}}</text><text v-if="message" role="status" class="modal-copy">{{message}}</text><text v-if="!configured&&!busy" class="modal-copy">正式家庭权益尚未配置。本机开发功能不代表购买授权。</text><view v-for="feature in features" :key="feature.feature" class="feature-row"><view><text>{{names[feature.feature]}}</text><text>{{feature.active?'已开启':'尚未开启或已到期'}}{{feature.expiresAt?` · 至 ${new Date(feature.expiresAt).toLocaleDateString('zh-CN')}`:''}}</text><text v-if="feature.sources.includes('manual-test')">包含人工测试开通</text><text v-if="feature.sources.includes('purchase')">包含已核验购买权益</text></view><text class="feature-status">{{feature.actions.writeAdvanced?'可使用高级功能':'已有资料保留'}}</text></view><button role="button" tabindex="0" class="outline-button" :disabled="busy||revoked" @click="run(refresh)">刷新权益与订单</button><text class="section-title">可选功能</text><text v-if="!paymentPlatform" class="modal-copy">当前付款渠道适用于网页版。移动端可查看已开通权益与订单，原生购买渠道待配置。</text><text v-if="!products.length" class="modal-copy">当前未配置商品和价格，不能购买。</text><text v-else-if="!providerReady" class="modal-copy">支付渠道尚未配置，当前不会发起付款。</text><view v-for="product in products" :key="product.id" class="billing-product"><view><text>{{product.title}}</text><text>{{names[product.feature]}} · {{product.durationDays}} 天 · {{price(product.amountMinor)}}</text></view><button role="button" tabindex="0" class="quiet-button" :disabled="!canPurchase||busy||revoked" :aria-label="`购买 ${product.title}`" @click="buy(product)">下单 / 重试</button></view><template v-if="manager"><text class="section-title">家庭订单 · {{orders.length}} 笔</text><view v-for="order in orders" :key="order.id" class="billing-order"><text>{{order.title}} · {{price(order.amountMinor)}} · {{states[order.status]||'等待核验'}}</text><text class="modal-copy">{{new Date(order.createdAt).toLocaleString('zh-CN')}}</text><view class="scene-options"><button v-if="order.status==='PENDING'&&order.checkoutUrl" role="button" tabindex="0" class="quiet-button" :disabled="busy||!paymentPlatform" @click="openCheckout(order)">前往支付</button><button role="button" tabindex="0" class="quiet-button" :disabled="!providerReady||busy" @click="query(order)">查询支付 / 退款结果</button><button v-if="['CREATED','PENDING'].includes(order.status)" role="button" tabindex="0" class="text-button" :disabled="!providerReady||busy" @click="closeOrder(order)">关闭订单</button><button v-if="order.status==='PAID'" role="button" tabindex="0" class="text-button" :disabled="!providerReady||busy" @click="refund(order)">申请整单退款</button></view></view></template></view>
</template>
<style scoped>.billing-manager{display:flex;flex-direction:column;gap:18px;min-width:0;padding-top:24px;border-top:1px solid #e3e8f0}.billing-product{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px;border:1px solid #e3e8f0;border-radius:10px}.billing-product>view,.billing-order{display:flex;flex-direction:column;gap:10px}.billing-order{padding:16px;background:#f7f9fc;border-radius:10px}.billing-manager .scene-options{flex-wrap:wrap}</style>
